/* MODULE tu04 · Bước 8 Tối ưu · Giới thiệu và truyền miệng
   9 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tu04', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tu04-01', skill:'measure', read:'7 phút', t:'Mỗi khách hàng thật sự mang về bao nhiêu khách mới?',
  situation:'Một app học tiếng Anh ở Hà Nội mở chương trình "mời bạn nhận 1 tháng miễn phí". Sau một tháng, 2.000 học viên cũ đã gửi tổng cộng 1.600 lời mời, và 240 người được mời đăng ký học. Sếp hỏi: "Vậy chương trình tự lan được chưa, hay vẫn phải đổ tiền quảng cáo?"',
  concept:{ name:'Hệ số lan truyền (K)',
    body:'Hệ số lan truyền cho biết <b>trung bình mỗi khách hiện có kéo về bao nhiêu khách mới</b>. Nó bằng số lời mời trung bình mỗi khách gửi nhân với tỉ lệ người được mời chuyển thành khách. Nếu K lớn hơn 1, mỗi lớp khách tự sinh ra lớp sau lớn hơn — tăng trưởng tự nuôi. K nhỏ hơn 1 vẫn có ích: nó là phần khách "tặng thêm" trên mỗi khách bạn mua bằng quảng cáo, nhưng không tự chạy được. Chia cho <b>toàn bộ khách</b>, không chỉ người đã đi mời.' },
  example:'Mỗi học viên gửi trung bình 1.600 ÷ 2.000 = 0,8 lời mời. Tỉ lệ người được mời đăng ký: 240 ÷ 1.600 = 15%. K = 0,8 × 15% = 0,12. Nghĩa là cứ 100 học viên mua bằng quảng cáo, app được tặng thêm khoảng 12 học viên. Chương trình có ích, nhưng còn rất xa mức tự lan; quảng cáo vẫn là động cơ chính, và việc cần làm là tăng số lời mời hoặc tỉ lệ nhận lời.',
  takeaway:'K = lời mời mỗi khách × tỉ lệ nhận lời; dưới 1 là phần thưởng thêm, không phải động cơ.',
  apply:'Lấy số liệu một chương trình giới thiệu bạn biết, tính K trong 60 giây và nói nó là "động cơ" hay "phần thêm".',
  mistakes:['Chỉ chia cho số khách đã đi mời, làm K phình to.','Thấy K dương là tưởng chương trình tự lan, cắt quảng cáo.'],
  q:[
  { type:'mcq', stem:'Trước khi tính: 2.000 học viên, 240 người mới nhờ giới thiệu. Bạn đoán chương trình này đang ở trạng thái nào?',
    options:[{k:'a',t:'Đã tự lan, vì 240 người mới là con số rất lớn với một app nhỏ'},{k:'b',t:'Có ích nhưng chưa tự lan: mỗi khách kéo về chưa tới một khách'},
             {k:'c',t:'Thất bại, vì chưa tới một nửa học viên chịu gửi lời mời'},{k:'d',t:'Chưa kết luận được gì nếu chưa biết chi phí quảng cáo'}],
    answer:'b', why:{a:'Con số tuyệt đối không nói lên việc tự lan; phải so với số khách đang có.',
      b:'Đúng. 240 trên 2.000 là khoảng 0,12 khách mới mỗi khách — có thêm nhưng xa mức 1.',
      c:'Tỉ lệ người đi mời thấp không có nghĩa là thất bại; 240 khách gần như miễn phí vẫn là giá trị.',
      d:'Chi phí quảng cáo cần cho bài toán lãi, nhưng câu hỏi tự lan hay không chỉ cần số lời mời và tỉ lệ nhận lời.'} },
  { type:'mcq', stem:'K = 0,12. Sếp muốn cắt nửa ngân sách quảng cáo vì "đã có giới thiệu lo". Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý cắt, vì giới thiệu mang khách miễn phí thay cho quảng cáo'},{k:'b',t:'Cắt toàn bộ quảng cáo và dồn tiền vào tăng thưởng giới thiệu gấp đôi'},
             {k:'c',t:'Giữ quảng cáo; thử tăng lời mời hoặc tỉ lệ nhận lời rồi đo lại K'},{k:'d',t:'Dừng chương trình giới thiệu vì K quá thấp, không đáng công vận hành'}],
    answer:'c', why:{a:'Với K nhỏ, giới thiệu chỉ nhân thêm 12% trên lượng khách quảng cáo mang về; cắt quảng cáo là cắt luôn nguồn sinh lời mời.',
      b:'Tăng thưởng chưa chắc tăng K, và bỏ hết quảng cáo thì không còn khách mới để đi mời.',
      c:'Đúng. Quảng cáo vẫn là động cơ; giới thiệu là đòn bẩy cần tối ưu từng thành phần.',
      d:'12 khách thêm trên mỗi 100 khách vẫn là giá trị, thường rẻ hơn quảng cáo.'} },
  { type:'calc', stem:'Một shop mỹ phẩm có 5.000 khách. Mỗi khách gửi trung bình 1,2 lời mời, 10% người được mời mua hàng. Hệ số lan truyền K là bao nhiêu?',
    unit:'', ans:0.12, tol:0.005, wrong:[[1.2,'QUEN_TI_LE_CHUYEN_DOI'],[600,'NHAM_SO_TUYET_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['K = số lời mời mỗi khách × tỉ lệ người được mời mua.','1,2 × 10% = <b>0,12</b>.'] },
  { type:'calc', stem:'App có 4.000 khách, nhưng chỉ 1.000 khách đi mời, mỗi người mời 2 bạn; 20% người được mời đăng ký. K tính trên toàn bộ khách là bao nhiêu?',
    unit:'', ans:0.1, tol:0.005, wrong:[[0.4,'QUEN_TI_LE_GIOI_THIEU'],[2,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_GIOI_THIEU'],
    steps:['Tổng lời mời = 1.000 × 2 = 2.000; mỗi khách trung bình 2.000 ÷ 4.000 = 0,5 lời mời.','K = 0,5 × 20% = <b>0,1</b>.','Nếu chia cho 1.000 người đi mời sẽ ra 0,4 — giả định ai cũng đi mời.'] },
  { type:'mcq', stem:'Hai phương án tăng K cùng chi phí: (1) nhắc mời bạn để lời mời mỗi khách tăng từ 0,8 lên 1,0; (2) sửa trang nhận lời để tỉ lệ nhận lời tăng từ 15% lên 20%. Phương án nào tăng K nhiều hơn?',
    options:[{k:'a',t:'Phương án 1, vì số lời mời luôn quan trọng hơn chất lượng trang'},{k:'b',t:'Bằng nhau, vì cả hai đều tăng thêm đúng 0,2 đơn vị ở một thừa số'},
             {k:'c',t:'Phương án 1, vì 0,2 lời mời lớn hơn 5 điểm phần trăm'},{k:'d',t:'Phương án 2: K lên 0,16, còn phương án 1 chỉ lên 0,15'}],
    answer:'d', why:{a:'Không có thừa số nào "luôn" quan trọng hơn; phải nhân ra mới biết.',
      b:'Hai thừa số có đơn vị khác nhau, không cộng trừ so sánh trực tiếp được.',
      c:'So con số tăng thêm của hai đại lượng khác đơn vị là sai; cần tính K mới.',
      d:'Đúng. 1,0 × 15% = 0,15; 0,8 × 20% = 0,16.'} },
  { type:'mcq', stem:'Một chuỗi trà sữa báo K = 1,3 sau tuần khai trương nhờ tặng ly miễn phí cho cả hai người. Bạn nên đọc con số này thế nào?',
    options:[{k:'a',t:'Chuỗi đã có tăng trưởng tự lan lâu dài, có thể ngừng quảng cáo ngay'},{k:'b',t:'Một tuần có quà lớn chưa đủ; theo dõi K khi quà giảm và theo từng lớp'},
             {k:'c',t:'K trên 1 là không thể có thật, chắc chắn số liệu bị đếm sai'},{k:'d',t:'Tăng thêm quà để đẩy K lên 2 trước khi đối thủ kịp phản ứng'}],
    answer:'b', why:{a:'K cao lúc khai trương thường do quà và sự mới lạ; nó hay tụt khi hai yếu tố này hết.',
      b:'Đúng. K phải giữ được qua nhiều lớp khách và khi thưởng về mức bền vững mới đáng tin.',
      c:'K trên 1 hiếm nhưng có thể xảy ra trong thời gian ngắn.',
      d:'Tăng quà khi chưa biết khách có quay lại không là mua tăng trưởng lỗ.'} },
  { type:'mcq', stem:'Nhân viên báo: "K = 0,6 vì mỗi người đi mời kéo được 0,6 khách". Chỉ 25% khách đi mời. Điều gì sai trong cách tính?',
    options:[{k:'a',t:'Phải nhân thêm giá trị đơn hàng thì K mới có ý nghĩa'},{k:'b',t:'K phải tính theo tháng, không được tính theo người'},
             {k:'c',t:'Chia cho người đi mời; tính trên toàn bộ khách thì K chỉ khoảng 0,15'},{k:'d',t:'Tỉ lệ 25% người đi mời đã quá thấp nên K chắc chắn phải bằng 0'}],
    answer:'c', why:{a:'K đo số khách, không đo tiền; giá trị đơn hàng dùng ở bài toán lãi.',
      b:'K có thể đo trong một kỳ, nhưng đơn vị vẫn là khách mới trên mỗi khách.',
      c:'Đúng. 0,6 × 25% = 0,15 khách mới trên mỗi khách hiện có.',
      d:'25% người đi mời vẫn mang về khách; K thấp nhưng không bằng 0.'} } ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tu04-02', skill:'channel', read:'6 phút', t:'Thưởng cho người mời, người được mời, hay cả hai?',
  situation:'Một ví điện tử mới đang tặng 50.000đ cho người giới thiệu khi bạn bè mở ví. Tỉ lệ người được mời mở ví chỉ 6%. Nhóm marketing có đúng 50.000đ cho mỗi khách mới và phải chọn: giữ nguyên, chuyển hết cho người được mời, hay chia đôi mỗi bên 25.000đ.',
  concept:{ name:'Thưởng một phía và thưởng hai phía',
    body:'Thưởng cho người mời làm họ <b>chịu gửi lời mời</b>. Thưởng cho người được mời làm lời mời <b>dễ nhận hơn</b>, và giúp người mời không ngại vì mình đang "tặng" bạn chứ không "kiếm tiền" từ bạn. Chia hai phía thường hợp khi sản phẩm cần người mới vượt một rào cản (mở ví, cài app, mua lần đầu). Nếu vấn đề là không ai chịu mời, dồn thưởng cho người mời. Nếu lời mời đã nhiều mà ít người nhận, dồn cho người được mời. Hãy nhìn thừa số nào đang yếu.' },
  example:'Ví điện tử có nhiều lời mời được gửi đi (khách thích kiếm 50.000đ), nhưng chỉ 6% bạn bè mở ví: rào cản nằm ở phía người nhận. Chia đôi 25.000đ – 25.000đ: người mời vẫn có động lực, còn người được mời thấy lý do để thử. Thử trên một nhóm, tỉ lệ nhận lời lên 10% trong khi lời mời chỉ giảm nhẹ — K tăng mà chi phí mỗi khách mới không đổi.',
  takeaway:'Thưởng vào đúng thừa số đang yếu: thiếu lời mời thì thưởng người mời, thiếu người nhận thì thưởng người được mời.',
  apply:'Chọn một app bạn dùng có chương trình mời bạn. Nói trong 60 giây: thưởng đang cho ai, và thừa số nào của họ có vẻ yếu.',
  mistakes:['Mặc định thưởng người mời vì "họ là người làm việc".','Tăng thưởng người mời khi vấn đề nằm ở người nhận không chịu thử.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: nhiều lời mời nhưng chỉ 6% người được mời mở ví. Bạn đoán tiền thưởng nên dịch về phía nào?',
    options:[{k:'a',t:'Về người được mời, vì rào cản đang nằm ở phía người nhận'},{k:'b',t:'Giữ nguyên cho người mời, vì họ mới là người bỏ công ra đi mời bạn bè'},
             {k:'c',t:'Tăng thêm cho người mời để họ mời được nhiều hơn nữa'},{k:'d',t:'Bỏ thưởng, vì 6% cho thấy sản phẩm chưa đủ tốt'}],
    answer:'a', why:{a:'Đúng. Lời mời đã có; thứ thiếu là lý do để người nhận hành động.',
      b:'Người mời đang làm tốt phần mình; giữ nguyên không sửa được chỗ yếu.',
      c:'Thêm lời mời vào một phễu nhận lời 6% chỉ tốn thêm tiền cho kết quả nhỏ.',
      d:'Tỉ lệ nhận lời thấp thường do rào cản thử lần đầu, chưa chắc do sản phẩm kém.'} },
  { type:'mcq', stem:'Một thương hiệu nồi chiên có 30% khách hài lòng nói "sẵn sàng giới thiệu" nhưng chỉ 3% thực sự gửi mã. Người nhận mã thì mua khá tốt. Bạn chọn cách chia thưởng nào?',
    options:[{k:'a',t:'Dồn thưởng cho người được mời để họ mua nhiều hơn nữa'},{k:'b',t:'Dồn thưởng cho người mời, kèm nút chia sẻ sẵn sau khi mua'},
             {k:'c',t:'Chia đôi hai phía như các ví điện tử đang làm cho an toàn'},{k:'d',t:'Tặng quà cho mọi khách mua hàng, không cần gắn với việc mời bạn'}],
    answer:'b', why:{a:'Người nhận đã mua tốt; thứ yếu là lời mời không được gửi đi.',
      b:'Đúng. Thừa số yếu là số lời mời; thưởng và làm dễ việc gửi mã cho người mời.',
      c:'Bắt chước ngành khác mà không nhìn thừa số yếu của mình là tiêu tiền dàn trải.',
      d:'Quà không gắn hành vi mời thì không tạo thêm lời mời nào.'} },
  { type:'mcq', stem:'Vì sao thưởng hai phía thường làm người mời bớt ngại hơn thưởng một phía?',
    options:[{k:'a',t:'Vì tổng tiền thưởng hai phía luôn lớn hơn thưởng một phía'},{k:'b',t:'Vì người được mời sẽ tự đi mời lại người mời ngay sau đó'},
             {k:'c',t:'Vì hai phía giúp thương hiệu tránh phải tính thuế trên tiền thưởng'},{k:'d',t:'Người mời thấy mình đang tặng quà cho bạn, không phải kiếm lời từ bạn'}],
    answer:'d', why:{a:'Tổng tiền có thể bằng nhau; ở tình huống trên vẫn là 50.000đ.',
      b:'Người được mời không mời ngược lại người đã là khách.',
      c:'Bài này không bàn thuế; động lực tâm lý mới là lý do chính.',
      d:'Đúng. Khi bạn cũng được lợi, lời mời giống món quà hơn là lời chào hàng.'} },
  { type:'calc', stem:'Ví điện tử: 10.000 lời mời mỗi tháng, tỉ lệ nhận lời 6%, thưởng 50.000đ cho mỗi khách mới. Sau khi chia đôi thưởng, lời mời còn 9.000 nhưng tỉ lệ nhận lời lên 10%. Số khách mới mỗi tháng tăng thêm bao nhiêu?',
    unit:'khách', ans:300, tol:0.5, wrong:[[900,'QUEN_TI_LE_CHUYEN_DOI'],[400,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Trước: 10.000 × 6% = 600 khách.','Sau: 9.000 × 10% = 900 khách.','Tăng thêm: 900 − 600 = <b>300 khách</b>.'] },
  { type:'mcq', stem:'Một nhãn thời trang cao cấp thử tặng người được mời mã giảm 30%. Doanh số tăng nhưng khách cũ phàn nàn thương hiệu "rẻ đi". Nên điều chỉnh gì?',
    options:[{k:'a',t:'Bỏ hẳn chương trình giới thiệu vì không hợp với hàng cao cấp'},{k:'b',t:'Tăng mức giảm lên 40% để doanh số tăng nhanh hơn nữa'},
             {k:'c',t:'Đổi thưởng tiền sang đặc quyền: sửa đồ miễn phí, xem bộ sưu tập sớm'},{k:'d',t:'Chỉ gửi mã giảm giá cho người lạ, không gửi cho bạn bè khách cũ'}],
    answer:'c', why:{a:'Giới thiệu rất hợp hàng cao cấp; vấn đề là hình thức thưởng.',
      b:'Giảm sâu hơn càng làm mòn hình ảnh cao cấp mà khách cũ đang lo.',
      c:'Đúng. Thưởng bằng đặc quyền vẫn tạo lý do thử mà không kéo giá trị cảm nhận xuống.',
      d:'Người lạ không phải là người được giới thiệu; câu này làm mất chính cơ chế giới thiệu.'} },
  { type:'mcq', stem:'Số liệu: mỗi khách gửi 0,3 lời mời, tỉ lệ nhận lời 25%. Thưởng đang chia đều hai phía. Bước tiếp theo hợp lý nhất?',
    options:[{k:'a',t:'Tăng phần cho người được mời, vì tỉ lệ nhận lời có thể tăng nữa'},{k:'b',t:'Giữ nguyên, vì chia hai phía luôn là cách tốt nhất'},
             {k:'c',t:'Dịch thưởng về người mời và tìm lúc thuận tiện để nhắc họ mời'},{k:'d',t:'Bỏ thưởng người mời, vì họ đã mời rất ít, thưởng là phí tiền'}],
    answer:'c', why:{a:'25% nhận lời đã khá tốt; 0,3 lời mời mới là chỗ nghẽn.',
      b:'Không có cách chia nào luôn tốt nhất; nó tuỳ thừa số yếu.',
      c:'Đúng. Lời mời quá ít; cần động lực và thời điểm cho người mời.',
      d:'Bỏ thưởng người mời sẽ làm số lời mời vốn đã ít càng ít hơn.'} },
  { type:'mcq', stem:'Grab từng có chương trình mã mời bạn mà cả hai bên đều nhận ưu đãi chuyến đi. Với một app gọi xe mới, lý do chính để thưởng người được mời là gì?',
    options:[{k:'a',t:'Để người được mời trở thành tài xế thay vì hành khách'},{k:'b',t:'Để người mời có thêm tiền và tự đi xe nhiều hơn nữa'},
             {k:'c',t:'Để tránh phải chạy quảng cáo trên mạng xã hội'},{k:'d',t:'Chuyến đầu với app lạ có rủi ro; ưu đãi giúp người mới dám thử'}],
    answer:'d', why:{a:'Chương trình mời hành khách không nhằm tuyển tài xế.',
      b:'Đó là tác dụng của thưởng người mời, không phải người được mời.',
      c:'Giới thiệu bổ sung cho quảng cáo, không thay thế hoàn toàn.',
      d:'Đúng. Ưu đãi hạ rào cản thử lần đầu ở phía người nhận.'} } ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tu04-03', skill:'measure', read:'7 phút', t:'Thưởng giới thiệu bao nhiêu thì vẫn còn lãi?',
  situation:'Một thương hiệu cà phê hạt bán online, đơn đầu trung bình 300.000đ, biên lãi gộp 40%. Khách mới mua trung bình 3 đơn trong đời. Họ định thưởng 100.000đ cho người mời và 100.000đ cho người được mời. Một bạn trong nhóm nói: "Lãi mỗi đơn 120.000đ, thưởng 200.000đ là lỗ rồi."',
  concept:{ name:'Trần thưởng giới thiệu',
    body:'Mức thưởng tối đa là phần <b>lãi gộp</b> mà một khách mới mang lại trong đời trừ đi phần lãi bạn muốn giữ. Không so thưởng với doanh thu, cũng không chỉ so với lãi đơn đầu nếu khách thật sự quay lại. Nhưng phải tính thưởng trên <b>khách thật sự mua</b>: thưởng người mời thường chỉ trả khi bạn bè mua, còn ưu đãi người được mời chỉ tốn khi họ dùng. So thưởng với chi phí có một khách qua quảng cáo để biết đây là kênh rẻ hay đắt.' },
  example:'Lãi gộp mỗi đơn: 300.000 × 40% = 120.000đ. Ba đơn: 360.000đ lãi gộp trong đời. Thưởng hai phía 200.000đ còn lại 160.000đ — vẫn lãi, nếu khách mới thật sự mua đủ 3 đơn. Bạn trong nhóm chỉ nhìn đơn đầu nên thấy lỗ. Nhưng nếu khách đến vì quà chỉ mua 1 đơn rồi đi, 120.000 − 200.000 = lỗ 80.000đ. Vì vậy nhóm quyết định trả 100.000đ cho người mời chỉ khi bạn họ mua đơn thứ hai.',
  takeaway:'Thưởng giới thiệu so với lãi gộp trong đời của khách mới, và trả theo hành vi mua thật.',
  apply:'Với một sản phẩm bạn biết giá, ước lãi gộp mỗi đơn và số đơn trong đời, rồi nói mức thưởng tối đa bạn dám trả.',
  mistakes:['So thưởng với doanh thu thay vì lãi gộp.','Giả định khách đến vì quà sẽ trung thành như khách tự tìm đến.'],
  q:[
  { type:'mcq', stem:'Trước khi tính: đơn 300.000đ, lãi gộp 40%, khách mua 3 đơn. Thưởng hai phía tổng 200.000đ. Bạn đoán sao?',
    options:[{k:'a',t:'Lỗ, vì 200.000đ lớn hơn lãi 120.000đ của đơn đầu tiên'},{k:'b',t:'Lãi thoải mái, vì 200.000đ nhỏ hơn doanh thu 900.000đ của ba đơn'},
             {k:'c',t:'Có thể lãi nếu khách mới thật sự mua đủ các đơn sau'},{k:'d',t:'Hoà vốn, vì thưởng luôn được tính vào giá bán sẵn rồi'}],
    answer:'c', why:{a:'Chỉ nhìn đơn đầu bỏ qua lãi của các đơn sau.',
      b:'So với doanh thu là sai; phải so với lãi gộp 360.000đ.',
      c:'Đúng. 360.000đ lãi gộp trong đời vẫn trên 200.000đ, với điều kiện khách quay lại thật.',
      d:'Giá bán không tự chứa thưởng giới thiệu; đây là chi phí thêm.'} },
  { type:'mcq', stem:'Bạn lo khách đến vì quà chỉ mua một đơn. Bạn chọn thiết kế thưởng nào?',
    options:[{k:'a',t:'Trả ngay 100.000đ cho người mời khi bạn bè vừa bấm vào đường dẫn mời'},{k:'b',t:'Trả thưởng người mời khi bạn họ mua đơn thứ hai'},
             {k:'c',t:'Giảm thưởng xuống 20.000đ mỗi bên để khỏi lỗ trong mọi trường hợp'},{k:'d',t:'Tăng thưởng người được mời để họ có lý do mua nhiều đơn hơn'}],
    answer:'b', why:{a:'Trả theo lượt bấm là trả cho hành vi không tạo lãi và dễ bị gian lận.',
      b:'Đúng. Gắn thưởng với hành vi tạo lãi thật khiến chương trình an toàn hơn.',
      c:'Thưởng quá thấp có thể làm chương trình mất sức hút, trong khi trần thật còn cao.',
      d:'Ưu đãi lần đầu không tạo thói quen mua lại; nó chỉ làm đơn đầu rẻ hơn.'} },
  { type:'calc', stem:'Đơn trung bình 300.000đ, biên lãi gộp 40%, khách mới mua 3 đơn trong đời. Thương hiệu muốn giữ lại ít nhất 160.000đ lãi gộp mỗi khách mới. Tổng thưởng tối đa cho một khách mới là bao nhiêu?',
    unit:'đồng', ans:200000, tol:1, wrong:[[740000,'LTV_TINH_DOANH_THU'],[-40000,'SAI_TINH_TOAN']], errors:['LTV_TINH_DOANH_THU'],
    steps:['Lãi gộp mỗi đơn = 300.000 × 40% = 120.000đ.','Lãi gộp trong đời = 3 × 120.000 = 360.000đ.','Thưởng tối đa = 360.000 − 160.000 = <b>200.000đ</b>.'] },
  { type:'calc', stem:'Thưởng người mời 100.000đ chỉ trả khi bạn mua. Mỗi tháng có 2.000 lời mời, 15% người được mời mua. Chi phí thưởng người mời mỗi tháng là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:30, tol:0.1, wrong:[[200,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Số bạn mua = 2.000 × 15% = 300.','Chi phí = 300 × 100.000 = 30.000.000đ = <b>30 triệu đồng</b>.'] },
  { type:'mcq', stem:'Chi phí có một khách qua quảng cáo là 250.000đ; chi phí thưởng cho một khách qua giới thiệu là 200.000đ. Khách giới thiệu mua lại nhiều hơn. Kết luận hợp lý?',
    options:[{k:'a',t:'Hai kênh ngang nhau vì chênh chỉ 50.000đ, không cần ưu tiên'},{k:'b',t:'Quảng cáo tốt hơn vì mang khách nhanh và đều đặn hơn giới thiệu'},
             {k:'c',t:'Dồn hết ngân sách quảng cáo sang thưởng giới thiệu từ tháng sau'},{k:'d',t:'Giới thiệu vừa rẻ hơn vừa cho khách tốt hơn; đáng đầu tư thêm'}],
    answer:'d', why:{a:'Chênh chi phí cộng chênh chất lượng khách là lý do rõ để ưu tiên.',
      b:'Tốc độ là ưu điểm của quảng cáo, nhưng không phủ nhận giá trị của giới thiệu.',
      c:'Giới thiệu cần khách từ quảng cáo để có người đi mời; không thể dồn hết.',
      d:'Đúng. Rẻ hơn mỗi khách và khách quay lại nhiều hơn.'} },
  { type:'mcq', stem:'Một chuỗi phòng gym tính: mỗi hội viên mới đóng 6 triệu/năm, nên thưởng 3 triệu cho người mời. Điều họ bỏ sót quan trọng nhất là gì?',
    options:[{k:'a',t:'Đóng 6 triệu là doanh thu; phải tính trên lãi gộp sau chi phí vận hành'},{k:'b',t:'Chỉ cần kiểm tra xem đối thủ đang thưởng giới thiệu bao nhiêu là đủ'},
             {k:'c',t:'Phòng gym không hợp để làm chương trình giới thiệu'},{k:'d',t:'Thưởng phải trả bằng tiền mặt thì hội viên mới chịu đi mời'}],
    answer:'a', why:{a:'Đúng. Nửa doanh thu có thể vượt cả lãi gộp một năm.',
      b:'Mức thưởng của đối thủ không cho biết mình còn lãi hay không.',
      c:'Gym rất hợp giới thiệu vì người ta hay rủ bạn đi tập cùng.',
      d:'Hình thức thưởng là chuyện sau; lỗi chính là tính trên doanh thu.'} },
  { type:'mcq', stem:'Thưởng đã tính dựa trên 3 đơn trong đời. Sau ba tháng, khách từ giới thiệu chỉ mua trung bình 1,5 đơn. Bạn làm gì?',
    options:[{k:'a',t:'Giữ nguyên thưởng, vì theo kế hoạch ban đầu vẫn còn lãi'},{k:'b',t:'Tính lại trần thưởng theo số đơn thật và đổi điều kiện trả thưởng'},
             {k:'c',t:'Tăng thưởng để khách mới thấy hấp dẫn và mua nhiều đơn hơn'},{k:'d',t:'Chờ thêm một năm nữa rồi mới đánh giá, vì ba tháng là quá ngắn'}],
    answer:'b', why:{a:'Kế hoạch dựa trên giả định đã sai; tiếp tục là trả thưởng lỗ.',
      b:'Đúng. 1,5 × 120.000 = 180.000đ lãi gộp, thấp hơn 200.000đ thưởng.',
      c:'Thưởng lớn hơn thu hút thêm người săn quà, càng ít mua lại.',
      d:'Chờ một năm với chương trình đang lỗ là để thiệt hại tích luỹ.'} } ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tu04-04', skill:'comm', read:'6 phút', t:'Nên xin khách giới thiệu vào lúc nào?',
  situation:'Một spa ở Đà Nẵng gửi tin nhắn "Mời bạn bè, nhận voucher 100.000đ" cho mọi khách vào ngày đầu tháng. Tỉ lệ khách bấm vào chỉ 1%. Chị quản lý để ý: khách hay khen ngay sau buổi massage, khi đang uống trà ở quầy, nhưng lúc đó không ai nhắc chuyện giới thiệu.',
  concept:{ name:'Khoảnh khắc hài lòng cao nhất',
    body:'Người ta sẵn lòng giới thiệu nhất <b>ngay sau một trải nghiệm tốt</b>: vừa nhận hàng đẹp, vừa xong dịch vụ, vừa đạt kết quả (giảm cân, học xong khoá). Lúc đó cảm xúc còn nóng và câu chuyện còn rõ. Gửi lời xin giới thiệu vào một ngày ngẫu nhiên thì khách phải tự nhớ lại, nên ít người làm. Tìm khoảnh khắc này bằng cách nhìn khi nào khách khen, đánh giá cao hoặc quay lại, rồi đặt lời mời đúng chỗ đó, kèm cách chia sẻ thật dễ.' },
  example:'Spa đổi cách: nhân viên quầy đưa thẻ có mã QR "Tặng bạn một buổi gội đầu dưỡng sinh" khi khách đang uống trà sau massage, và gửi tin nhắn cảm ơn kèm đường dẫn mời trong vòng 2 giờ. Trong 1.000 khách của tháng, 80 người gửi mã, so với 10 người khi gửi tin nhắn đầu tháng. Voucher và sản phẩm không đổi; chỉ đổi thời điểm.',
  takeaway:'Xin giới thiệu khi khách vừa hài lòng, không phải khi lịch gửi tin của bạn tới hạn.',
  apply:'Với một dịch vụ bạn hay dùng, chỉ ra khoảnh khắc bạn hài lòng nhất và viết một câu mời giới thiệu đặt đúng lúc đó.',
  mistakes:['Gửi lời mời hàng loạt theo lịch, không theo trải nghiệm.','Xin giới thiệu ngay khi khách vừa trả tiền, trước khi họ dùng.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: spa gửi lời mời đầu tháng chỉ có 1% khách bấm. Bạn đoán nguyên nhân chính là gì?',
    options:[{k:'a',t:'Voucher 100.000đ quá nhỏ so với giá một buổi spa'},{k:'b',t:'Lời mời đến lúc khách không còn nhớ cảm giác hài lòng'},
             {k:'c',t:'Khách không thích dịch vụ nên không muốn giới thiệu cho ai'},{k:'d',t:'Tin nhắn nên được gửi qua email thay vì SMS thì mới hiệu quả'}],
    answer:'b', why:{a:'Có thể, nhưng khách vẫn khen ở quầy — thứ thiếu là thời điểm.',
      b:'Đúng. Lời mời tách khỏi trải nghiệm nên khách phải tự nhớ lại, ít ai làm.',
      c:'Khách hay khen sau buổi massage, nên không phải do không thích.',
      d:'Đổi kênh gửi không sửa được việc gửi sai thời điểm.'} },
  { type:'mcq', stem:'Một shop bán đồ bộ online muốn xin giới thiệu. Bạn chọn đặt lời mời ở đâu?',
    options:[{k:'a',t:'Trên trang thanh toán, ngay trước khi khách bấm đặt hàng'},{k:'b',t:'Trong tin nhắn khuyến mãi gửi toàn bộ danh sách khách vào ngày 15 hằng tháng'},
             {k:'c',t:'Trong gói hàng và tin hỏi thăm một ngày sau khi khách nhận hàng'},{k:'d',t:'Ở cuối trang chủ để ai muốn thì tự tìm'}],
    answer:'c', why:{a:'Lúc này khách chưa dùng sản phẩm; chưa có trải nghiệm để giới thiệu.',
      b:'Gửi theo lịch là đúng cách làm đang thất bại ở spa.',
      c:'Đúng. Mở hàng và mặc thử là lúc hài lòng rõ nhất.',
      d:'Chờ khách tự tìm thì gần như không ai làm.'} },
  { type:'calc', stem:'Spa có 1.000 khách mỗi tháng. Gửi đầu tháng: 1% khách gửi mã. Đưa thẻ sau buổi massage: 8% khách gửi mã. Mỗi mã gửi đi mang về trung bình 0,5 khách mới. Đổi thời điểm mang thêm bao nhiêu khách mới mỗi tháng?',
    unit:'khách', ans:35, tol:0.5, wrong:[[70,'QUEN_TI_LE_CHUYEN_DOI'],[40,'SAI_TINH_TOAN']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Trước: 1.000 × 1% = 10 mã → 10 × 0,5 = 5 khách.','Sau: 1.000 × 8% = 80 mã → 80 × 0,5 = 40 khách.','Thêm: 40 − 5 = <b>35 khách</b>.'] },
  { type:'mcq', stem:'Một khoá học online có điểm đánh giá cao nhất ở buổi 8 khi học viên làm xong dự án đầu tiên. Lời mời giới thiệu nên đặt ở đâu?',
    options:[{k:'a',t:'Ngay sau khi học viên nộp dự án và nhận nhận xét tốt'},{k:'b',t:'Ở buổi 1, khi học viên còn hào hứng nhất lúc vừa đăng ký'},
             {k:'c',t:'Sau buổi cuối, khi khoá học đã kết thúc hẳn'},{k:'d',t:'Trong email gửi học viên đã bỏ học giữa chừng để kéo lại'}],
    answer:'a', why:{a:'Đúng. Đạt kết quả đầu tiên là khoảnh khắc có chuyện để kể.',
      b:'Buổi 1 có hào hứng nhưng chưa có kết quả để kể.',
      c:'Sau buổi cuối vẫn được, nhưng cảm xúc có thể đã nguội và nhiều người đã bỏ.',
      d:'Người bỏ học ít hài lòng; xin giới thiệu lúc này dễ phản tác dụng.'} },
  { type:'mcq', stem:'Khách vừa gửi phàn nàn về giao hàng trễ, rồi được xử lý nhanh và hài lòng. Có nên xin giới thiệu ngay lúc đó?',
    options:[{k:'a',t:'Không bao giờ, vì khách từng phàn nàn thì sẽ không bao giờ giới thiệu'},{k:'b',t:'Có, nên gửi mã ngay trong tin nhắn xin lỗi để bù cho khách'},
             {k:'c',t:'Có thể, sau khi khách xác nhận hài lòng; xử lý tốt cũng là chuyện để kể'},{k:'d',t:'Chỉ khi khách tự nói muốn giới thiệu, không được chủ động hỏi'}],
    answer:'c', why:{a:'Khách được xử lý tốt đôi khi còn trung thành hơn.',
      b:'Xin giới thiệu khi đang xin lỗi dễ bị xem là không thật lòng.',
      c:'Đúng. Chờ xác nhận hài lòng rồi mới mời; lúc đó câu chuyện là "họ xử lý rất nhanh".',
      d:'Chủ động hỏi đúng lúc là điều nên làm.'} },
  { type:'mcq', stem:'Một app giao đồ ăn cho khách tuỳ chọn chia sẻ ngay trên màn hình đánh giá 5 sao. Vì sao chỗ này hiệu quả?',
    options:[{k:'a',t:'Vì màn hình đánh giá có nhiều chỗ trống để đặt nút bấm'},{k:'b',t:'Vì app đó bắt buộc khách phải chia sẻ mới cho đánh giá được'},
             {k:'c',t:'Vì người đánh giá 5 sao đã quen dùng app, không cần ưu đãi gì'},{k:'d',t:'Chấm 5 sao là tín hiệu hài lòng; lời mời xuất hiện đúng lúc đó'}],
    answer:'d', why:{a:'Chỗ trống không phải lý do; ý nghĩa của khoảnh khắc mới quan trọng.',
      b:'Bắt buộc chia sẻ sẽ làm khách khó chịu; ở đây là tuỳ chọn.',
      c:'Không cần ưu đãi không phải lý do chỗ đặt hiệu quả.',
      d:'Đúng. Khách vừa tự thể hiện hài lòng; lời mời chỉ nối tiếp cảm xúc đó.'} },
  { type:'mcq', stem:'Spa muốn gửi thêm lời mời qua tin nhắn. Thời điểm nào tốt nhất?',
    options:[{k:'a',t:'Trong vòng vài giờ sau buổi massage, kèm lời cảm ơn'},{k:'b',t:'Vào sáng thứ Hai, vì đó là lúc khách hay mở tin nhắn nhất trong tuần'},
             {k:'c',t:'Một tháng sau buổi cuối, để nhắc khách quay lại'},{k:'d',t:'Ngay khi khách đặt lịch hẹn, trước khi đến spa'}],
    answer:'a', why:{a:'Đúng. Cảm giác thư giãn còn rõ; lời mời gắn với trải nghiệm vừa có.',
      b:'Giờ mở tin cao không bù được việc tách lời mời khỏi trải nghiệm.',
      c:'Lúc này là nhắc quay lại, không phải lúc hài lòng nhất.',
      d:'Khách chưa trải nghiệm thì chưa có gì để giới thiệu.'} } ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tu04-05', skill:'creative', read:'6 phút', t:'Làm sao để khách tự kể về bạn mà không cần thưởng?',
  situation:'Một quán bún chả ở Hà Nội ngon, sạch, giá hợp lý, nhưng khách ăn xong ít ai nhắc lại với bạn bè. Quán bên cạnh bán bún chả "que tre" nướng kẹp tre, có bảng ghi "Ăn hết 3 suất trong 20 phút, miễn phí" — khách chụp ảnh và kể liên tục. Chủ quán hỏi: mình có cần giảm giá để được nói đến không?',
  concept:{ name:'Chuyện để kể',
    body:'Người ta không kể về thứ "tốt", họ kể về thứ <b>đáng kể</b>: khác thường, gây bất ngờ, dễ chụp, hay giúp người kể trông thú vị hoặc tốt bụng. Ngon và sạch là điều khách mong đợi, nên không thành chuyện. Truyền miệng tự nhiên cần một chi tiết cụ thể mà khách có thể nói lại trong một câu. Chi tiết đó phải thật và gắn với sản phẩm, không phải mẹo vô nghĩa. Nó rẻ hơn thưởng giới thiệu và bền hơn, vì khách kể vì muốn kể.' },
  example:'Quán bún chả thử một chi tiết: bưng nước mắm đựng trong bát sành nhỏ khắc tên quán, và tặng khách một chiếc chả viên nướng "ăn thử trước" khi ngồi xuống. Không giảm giá. Sau 2 tháng, trong 200 khách mới được hỏi, số người nói "bạn kể" tăng từ 20 lên 50. Khách lặp lại đúng một câu: "quán đó mời chả trước khi gọi món."',
  takeaway:'Tốt là điều kiện cần; khách chỉ kể khi có một chi tiết đáng kể nói được trong một câu.',
  apply:'Chọn một quán bạn thích. Nói trong 60 giây câu một câu bạn sẽ dùng để kể về nó với bạn bè — nếu không có, đó là việc cần tạo.',
  mistakes:['Nghĩ chất lượng tốt tự khắc được kể lại.','Tạo chi tiết gây sốc không liên quan đến sản phẩm.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: quán ngon, sạch nhưng ít được kể. Bạn đoán lý do chính là gì?',
    options:[{k:'a',t:'Khách chưa được thưởng khi giới thiệu nên không có động lực'},{k:'b',t:'Quán chưa chạy quảng cáo nên khách không biết đến'},
             {k:'c',t:'Ngon và sạch là điều khách chờ đợi, không thành chuyện'},{k:'d',t:'Món bún chả vốn đã phổ biến ở Hà Nội nên không bao giờ có ai muốn kể nữa'}],
    answer:'c', why:{a:'Quán bên cạnh không thưởng mà vẫn được kể; thưởng không phải thứ thiếu.',
      b:'Khách đã ăn ở quán; câu hỏi là vì sao họ không kể lại.',
      c:'Đúng. Đáp ứng đúng mong đợi không tạo ra câu chuyện.',
      d:'Món phổ biến vẫn được kể nếu có chi tiết khác thường, như quán bên cạnh.'} },
  { type:'mcq', stem:'Chủ quán có ngân sách nhỏ. Bạn chọn cách nào để khách tự kể?',
    options:[{k:'a',t:'Giảm 20% cho mọi khách trong một tháng để quán đông lên'},{k:'b',t:'Thêm một chi tiết bất ngờ gắn với món, nói được trong một câu'},
             {k:'c',t:'Treo biển ghi "Bún chả ngon nhất Hà Nội" ở cửa quán'},{k:'d',t:'Thuê nhiều người nổi tiếng đến ăn và đăng bài khen quán liên tục trong tuần'}],
    answer:'b', why:{a:'Giảm giá có thể đông lên nhưng khách kể "đang giảm giá", hết giảm là hết chuyện.',
      b:'Đúng. Một chi tiết thật, rẻ và gắn với món là thứ khách mang đi kể.',
      c:'Lời tự khen không phải chuyện khách muốn lặp lại.',
      d:'Tốn kém, và đó là quảng cáo trả tiền chứ không phải khách tự kể.'} },
  { type:'calc', stem:'Quán hỏi 200 khách mới "biết quán qua đâu". Trước khi thêm chi tiết mời chả: 20 người nói "bạn kể". Sau: 50 người. Tỉ lệ khách mới đến nhờ bạn kể tăng bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:15, tol:0.1, wrong:[[150,'NHAM_DIEM_PHAN_TRAM'],[30,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 20 ÷ 200 = 10%.','Sau: 50 ÷ 200 = 25%.','Tăng: 25% − 10% = <b>15 điểm phần trăm</b> (tăng tương đối 150%).'] },
  { type:'mcq', stem:'Chi tiết nào dưới đây có khả năng thành chuyện để kể nhất cho một tiệm giặt sấy?',
    options:[{k:'a',t:'Máy giặt đời mới nhất, giặt nhanh hơn các tiệm khác trong khu vực'},{k:'b',t:'Giá rẻ hơn các tiệm xung quanh 5%'},
             {k:'c',t:'Tiệm mở cửa từ 7 giờ sáng đến 9 giờ tối mọi ngày'},{k:'d',t:'Áo sơ mi trả kèm tờ ghi "nút thứ ba lỏng, tiệm đã khâu lại"'}],
    answer:'d', why:{a:'Nhanh hơn là cải tiến khách khó thấy và khó kể.',
      b:'Rẻ hơn 5% khó thấy và ít ai kể.',
      c:'Giờ mở cửa là thông tin, không phải chuyện.',
      d:'Đúng. Bất ngờ, cụ thể, cho thấy tận tâm — khách chụp và kể lại.'} },
  { type:'mcq', stem:'Một quán cà phê tạo chiêu đổ cà phê lên sàn "để may mắn" cho khách chụp ảnh. Khách chụp nhiều nhưng ít quay lại. Vấn đề là gì?',
    options:[{k:'a',t:'Chi tiết gây chú ý nhưng không gắn với giá trị của sản phẩm'},{k:'b',t:'Quán chưa đăng đủ ảnh lên mạng xã hội nên khách không biết'},
             {k:'c',t:'Khách chụp ảnh nhiều quá nên không kịp uống cà phê cho ngon'},{k:'d',t:'Chiêu này cần có thưởng giới thiệu đi kèm'}],
    answer:'a', why:{a:'Đúng. Được kể nhưng không liên quan cà phê ngon; người đến vì chiêu, không vì sản phẩm.',
      b:'Khách đã chụp nhiều; thiếu ảnh không phải vấn đề.',
      c:'Nghe hợp lý nhưng không giải thích việc không quay lại.',
      d:'Thưởng không sửa được chi tiết lệch khỏi sản phẩm.'} },
  { type:'mcq', stem:'Vì sao "một câu" lại quan trọng với chuyện để kể?',
    options:[{k:'a',t:'Vì mạng xã hội giới hạn số chữ trong mỗi bài đăng'},{k:'b',t:'Vì câu ngắn thì khách sẽ nhớ được tên của quán lâu hơn'},
             {k:'c',t:'Vì khách chỉ kể lại thứ họ nhắc được ngay khi đang nói chuyện'},{k:'d',t:'Vì câu ngắn thì quán tốn ít tiền in ấn bảng hiệu hơn'}],
    answer:'c', why:{a:'Giới hạn chữ không phải lý do; truyền miệng phần lớn là nói chuyện.',
      b:'Nhớ tên là lợi ích phụ; lý do chính là khả năng kể lại.',
      c:'Đúng. Khi nói chuyện, người ta chỉ lặp lại được thứ gọn và cụ thể.',
      d:'Chi phí in không liên quan đến truyền miệng.'} },
  { type:'mcq', stem:'Một thương hiệu nước mắm muốn được kể nhiều hơn. Bạn đề xuất gì?',
    options:[{k:'a',t:'Tăng độ đạm lên thêm 2 độ so với đối thủ và in số đó thật to trên nhãn'},{k:'b',t:'Chai có mã quét ra video ngư dân đánh mẻ cá làm ra chai đó'},
             {k:'c',t:'Giảm giá 10% và mở minigame đoán giá'},{k:'d',t:'Thưởng 10.000đ cho mỗi người giới thiệu thành công'}],
    answer:'b', why:{a:'Độ đạm là thông số tốt nhưng khó thành câu chuyện ngoài người sành.',
      b:'Đúng. Cụ thể, bất ngờ, gắn với nguồn gốc sản phẩm — dễ kể lại.',
      c:'Minigame tạo tương tác tạm thời, không tạo chuyện về sản phẩm.',
      d:'Đó là thưởng giới thiệu, không phải khách tự kể.'} } ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tu04-06', skill:'measure', read:'7 phút', t:'Chương trình giới thiệu tăng vọt — thật hay bị gian lận?',
  situation:'Một app mua sắm thưởng 50.000đ cho cả hai bên khi người mới đặt đơn đầu từ 100.000đ. Tuần này, khách mới qua giới thiệu tăng từ 400 lên 2.400. Nhóm vui mừng, cho đến khi kế toán thấy nhiều đơn giao cùng một địa chỉ, và nhiều tài khoản mới không bao giờ đặt đơn thứ hai.',
  concept:{ name:'Gian lận giới thiệu',
    body:'Khi thưởng bằng tiền, sẽ có người <b>tự mời chính mình</b>: tạo nhiều tài khoản, dùng nhiều số điện thoại, đặt đơn nhỏ rồi rút thưởng. Dấu hiệu: tăng đột biến, nhiều tài khoản chung thiết bị hoặc địa chỉ, tỉ lệ mua lại gần 0, người mời có hàng chục "bạn" trong một ngày. Chặn bằng thiết kế: trả thưởng sau khi đơn hoàn tất và qua thời gian đổi trả, giới hạn số lượt mỗi người, kiểm tra thiết bị và địa chỉ, thưởng bằng điểm dùng trong app thay vì tiền rút được.' },
  example:'Kiểm 2.400 khách mới: 1.800 tài khoản dùng chung 60 thiết bị và mua đúng một đơn. Chỉ 600 khách là thật. Tiền thưởng đã trả cho 1.800 tài khoản giả: 1.800 × 100.000đ = 180 triệu đồng mất trắng. Nhóm đổi luật: thưởng người mời trả sau 14 ngày, tối đa 10 lượt mỗi tháng, trả bằng điểm mua sắm. Tuần sau, khách mới qua giới thiệu còn 650, nhưng gần như đều là khách thật.',
  takeaway:'Chương trình giới thiệu tăng vọt thì kiểm tra trước khi ăn mừng; thiết kế thưởng để gian lận không có lời.',
  apply:'Nói trong 60 giây ba dấu hiệu bạn sẽ kiểm tra khi số khách mới từ giới thiệu tăng gấp năm lần trong một tuần.',
  mistakes:['Ăn mừng con số tăng mà không kiểm tra chất lượng khách.','Trả thưởng bằng tiền mặt ngay khi đặt đơn.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: khách mới qua giới thiệu tăng gấp 6 lần trong một tuần mà không có thay đổi gì khác. Phản ứng đầu tiên nên là gì?',
    options:[{k:'a',t:'Tăng ngân sách thưởng ngay, vì chương trình đang chạy rất tốt'},{k:'b',t:'Báo cáo thành tích lên sếp và tính mở rộng ra các thành phố khác'},
             {k:'c',t:'Tạm dừng chương trình vì tăng vọt như vậy chắc chắn là gian lận'},{k:'d',t:'Kiểm tra thiết bị, địa chỉ và tỉ lệ mua lại trước khi kết luận'}],
    answer:'d', why:{a:'Tăng ngân sách khi chưa kiểm là có thể trả thêm tiền cho kẻ gian.',
      b:'Báo thành tích khi chưa kiểm dễ phải rút lại sau.',
      c:'Không phải mọi tăng trưởng đều là gian lận; cần bằng chứng rồi mới dừng.',
      d:'Đúng. Đột biến không lý do là tín hiệu cần kiểm tra chất lượng.'} },
  { type:'mcq', stem:'Bạn phải sửa luật thưởng để gian lận không có lời mà khách thật vẫn thấy hấp dẫn. Bạn chọn gì?',
    options:[{k:'a',t:'Bắt người được mời gửi ảnh căn cước để xác minh danh tính'},{k:'b',t:'Trả thưởng sau thời gian đổi trả, bằng điểm, giới hạn lượt mỗi tháng'},
             {k:'c',t:'Giảm thưởng xuống 5.000đ để kẻ gian không còn thấy có lời'},{k:'d',t:'Ngừng chương trình giới thiệu và chuyển toàn bộ tiền sang chạy quảng cáo'}],
    answer:'b', why:{a:'Rào cản quá nặng làm khách thật bỏ đi và rủi ro dữ liệu cá nhân.',
      b:'Đúng. Mỗi điều kiện đánh vào một cách gian lận mà ít làm phiền khách thật.',
      c:'Thưởng quá thấp làm khách thật mất hứng, trong khi kẻ gian làm số lượng vẫn có thể có lời.',
      d:'Bỏ luôn kênh giá trị vì một lỗ hổng sửa được là phản ứng quá tay.'} },
  { type:'calc', stem:'Trong 2.400 khách mới qua giới thiệu, 1.800 là tài khoản giả. Mỗi khách mới được trả tổng 100.000đ thưởng (hai phía). Số tiền thưởng bị mất vào tài khoản giả là bao nhiêu triệu đồng?',
    unit:'triệu đồng', ans:180, tol:0.1, wrong:[[240,'SAI_MAU_SO'],[90,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO'],
    steps:['Thưởng mất = số tài khoản giả × thưởng mỗi khách.','1.800 × 100.000 = 180.000.000đ = <b>180 triệu đồng</b>.'] },
  { type:'calc', stem:'Sau khi sửa luật, tuần sau có 650 khách mới qua giới thiệu, ước 5% là giả. Tuần trước có 2.400 khách, 75% giả. Số khách thật mỗi tuần thay đổi thế nào (sau trừ trước)?',
    unit:'khách', ans:17.5, tol:0.6, wrong:[[-1750,'NHAM_SO_TUYET_DOI']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Trước: 2.400 × 25% = 600 khách thật.','Sau: 650 × 95% = 617,5 khách thật.','Thay đổi: 617,5 − 600 = <b>+17,5 khách</b> — số khách thật gần như giữ nguyên.'] },
  { type:'mcq', stem:'Một người mời có 45 "bạn" đăng ký trong một buổi tối, tất cả đặt đơn 100.000đ đến cùng một phường. Bạn đọc tín hiệu này thế nào?',
    options:[{k:'a',t:'Đây là người có ảnh hưởng lớn, nên mời làm đại sứ'},{k:'b',t:'Có dấu hiệu tự mời mình; tạm giữ thưởng và kiểm tra thêm'},
             {k:'c',t:'Nhóm bạn cùng khu phố rủ nhau mua, rất bình thường'},{k:'d',t:'Đơn đúng 100.000đ cho thấy app đặt ngưỡng thưởng hợp lý, cứ giữ nguyên'}],
    answer:'b', why:{a:'Người ảnh hưởng thật hiếm khi kéo 45 người đặt đúng một mức đơn trong vài giờ.',
      b:'Đúng. Số lượng dồn, đơn sát ngưỡng, cùng địa bàn là mẫu hình gian lận điển hình.',
      c:'Có thể một vài người, nhưng 45 người trong một tối với đơn giống nhau là bất thường.',
      d:'Đơn sát ngưỡng chính là dấu hiệu người ta chỉ mua đủ để lấy thưởng.'} },
  { type:'mcq', stem:'Vì sao thưởng bằng điểm dùng trong app giảm gian lận hơn thưởng tiền rút được?',
    options:[{k:'a',t:'Vì điểm có giá trị thấp hơn tiền mặt nên chẳng ai muốn nhận'},{k:'b',t:'Vì điểm được tính vào thuế thu nhập nên kẻ gian sợ bị phát hiện'},
             {k:'c',t:'Kẻ gian muốn tiền rút ra; điểm chỉ có giá trị với người thật sự mua'},{k:'d',t:'Vì điểm hết hạn nhanh nên ai cũng quên dùng'}],
    answer:'c', why:{a:'Điểm vẫn có giá trị với khách thật; ý là nó ít giá trị với kẻ gian.',
      b:'Bài này không bàn thuế; lý do là giá trị của điểm với từng loại người.',
      c:'Đúng. Điểm chỉ quy ra lợi ích khi mua hàng, nên tự mời mình không còn lời.',
      d:'Hạn dùng ngắn làm khách thật khó chịu, không phải lý do chính.'} },
  { type:'mcq', stem:'Sau khi siết luật, số khách mới qua giới thiệu giảm từ 2.400 xuống 650. Sếp lo chương trình "hỏng rồi". Bạn trả lời thế nào?',
    options:[{k:'a',t:'Đúng là hỏng, nên nới lỏng luật lại để số lượng tăng trở lại'},{k:'b',t:'Số khách thật gần như giữ nguyên; chỉ phần giả biến mất'},
             {k:'c',t:'Con số giảm vì đối thủ vừa chạy chương trình giới thiệu mạnh hơn'},{k:'d',t:'Chờ vài tháng nữa, khách sẽ tự quen với luật mới và số lượng sẽ quay lại mức cũ'}],
    answer:'b', why:{a:'Nới luật là mở cửa lại cho 1.800 tài khoản giả.',
      b:'Đúng. 600 khách thật trước, khoảng 617 sau — chương trình vẫn khoẻ, chỉ bớt tiền mất.',
      c:'Không có dữ kiện về đối thủ; sự sụt giảm đúng bằng phần giả đã bị lọc.',
      d:'Số cũ là số có gian lận; quay lại mức đó không phải mục tiêu.'} } ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tu04-07', skill:'channel', read:'6 phút', t:'Review và video của khách có đáng đầu tư như giới thiệu?',
  situation:'Một thương hiệu kem chống nắng nội địa bán trên Shopee có 150 đánh giá, điểm 4,8. Đối thủ có 3.000 đánh giá, 4,6 điểm, và hàng trăm video khách tự quay trên TikTok. Tỉ lệ người xem trang thành người mua của thương hiệu là 1,5%, của đối thủ ước khoảng 3%. Ngân sách tháng này chỉ đủ cho một việc.',
  concept:{ name:'Truyền miệng số: review và UGC',
    body:'Đánh giá và nội dung khách tự tạo (<b>UGC</b>) là lời giới thiệu gửi tới <b>người lạ</b> thay vì bạn bè. Người mua online không hỏi được ai, nên họ đọc đánh giá, xem ảnh và video thật. Số lượng đánh giá quan trọng không kém điểm: 4,8 trên 150 đánh giá ít thuyết phục hơn 4,6 trên 3.000. Cách tăng: xin đánh giá ngay khi khách nhận và dùng thử, làm dễ việc đăng ảnh, trả lời cả đánh giá xấu. Không mua đánh giá giả: bị phát hiện là mất lòng tin.' },
  example:'Thương hiệu dồn ngân sách vào xin đánh giá: thẻ cảm ơn trong hộp kèm hướng dẫn đăng ảnh, tin nhắn hỏi thăm sau 7 ngày dùng, và chọn 20 video thật của khách để đăng lại. Sau 2 tháng: 900 đánh giá, 4,7 điểm. Với 40.000 lượt xem trang mỗi tháng, tỉ lệ mua lên 2,2% — từ 600 lên 880 đơn mỗi tháng, không tăng tiền quảng cáo.',
  takeaway:'Đánh giá và video của khách là truyền miệng tới người lạ; số lượng thật quan trọng như điểm số.',
  apply:'Mở trang một sản phẩm bạn định mua. Nói trong 60 giây: bạn tin đánh giá nào nhất và vì sao.',
  mistakes:['Chỉ nhìn điểm sao, bỏ qua số lượng đánh giá.','Xoá hoặc lờ đi đánh giá xấu thay vì trả lời.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: 4,8 điểm với 150 đánh giá hay 4,6 điểm với 3.000 đánh giá — người mua lạ tin bên nào hơn?',
    options:[{k:'a',t:'4,8 điểm, vì điểm cao hơn luôn có nghĩa là sản phẩm tốt hơn'},{k:'b',t:'4,6 với 3.000 đánh giá, vì nhiều người đã mua và kiểm chứng'},
             {k:'c',t:'Hai bên như nhau vì chênh 0,2 điểm là quá nhỏ'},{k:'d',t:'Không bên nào, vì người mua không bao giờ đọc đánh giá'}],
    answer:'b', why:{a:'Điểm cao trên ít đánh giá dễ bị nghi ngờ hoặc dao động.',
      b:'Đúng. Số lượng lớn tạo cảm giác an toàn: nhiều người đã thử.',
      c:'Chênh điểm nhỏ nhưng chênh số lượng rất lớn.',
      d:'Người mua online đọc đánh giá thường xuyên; đó là nguồn tin chính.'} },
  { type:'mcq', stem:'Ngân sách chỉ đủ một việc. Với tỉ lệ mua 1,5% so với 3% của đối thủ, bạn chọn gì?',
    options:[{k:'a',t:'Tăng quảng cáo để kéo thêm lượt xem vào trang bán hàng'},{k:'b',t:'Giảm giá 20% để vượt đối thủ về giá trên sàn'},
             {k:'c',t:'Mua gói 1.000 đánh giá 5 sao từ dịch vụ để đuổi kịp đối thủ nhanh nhất'},{k:'d',t:'Xây quy trình xin đánh giá và ảnh thật từ khách đã mua'}],
    answer:'d', why:{a:'Đổ thêm người vào trang có tỉ lệ mua thấp là lãng phí; chỗ nghẽn ở niềm tin trên trang.',
      b:'Giảm giá làm mỏng lãi, trong khi vấn đề là thiếu bằng chứng từ khách.',
      c:'Đánh giá giả dễ bị phát hiện, mất lòng tin và có thể bị sàn phạt.',
      d:'Đúng. Tăng số đánh giá thật là sửa đúng chỗ nghẽn niềm tin.'} },
  { type:'calc', stem:'Trang có 40.000 lượt xem mỗi tháng. Tỉ lệ mua tăng từ 1,5% lên 2,2% nhờ đánh giá. Số đơn tăng thêm mỗi tháng là bao nhiêu?',
    unit:'đơn', ans:280, tol:0.5, wrong:[[880,'NHAM_SO_TUYET_DOI'],[28000,'NHAM_DIEM_PHAN_TRAM']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Trước: 40.000 × 1,5% = 600 đơn.','Sau: 40.000 × 2,2% = 880 đơn.','Tăng: 880 − 600 = <b>280 đơn</b>.'] },
  { type:'mcq', stem:'Một khách để lại đánh giá 1 sao: "Kem làm bết da". Bạn làm gì?',
    options:[{k:'a',t:'Trả lời công khai, hướng dẫn cách dùng cho da dầu và đề nghị hỗ trợ'},{k:'b',t:'Nhờ sàn xoá đánh giá vì nó làm giảm điểm trung bình của sản phẩm'},
             {k:'c',t:'Lờ đi, vì một đánh giá xấu giữa nhiều đánh giá tốt không ai để ý'},{k:'d',t:'Nhờ nhân viên viết thêm 5 đánh giá tốt để đẩy nó xuống dưới'}],
    answer:'a', why:{a:'Đúng. Người đọc sau thấy thương hiệu lắng nghe; đánh giá xấu được trả lời tốt tăng niềm tin.',
      b:'Xoá đánh giá thật thường không được và làm mất cơ hội thể hiện cách xử lý.',
      c:'Người mua hay đọc đánh giá xấu trước; lờ đi là bỏ lỡ cơ hội.',
      d:'Đánh giá nội bộ giả mạo là gian dối, có thể bị phát hiện.'} },
  { type:'mcq', stem:'Vì sao video khách tự quay thường thuyết phục hơn video quảng cáo của thương hiệu?',
    options:[{k:'a',t:'Vì video khách quay có chất lượng hình ảnh đẹp hơn'},{k:'b',t:'Vì thuật toán TikTok luôn ưu tiên video của người bình thường, không bao giờ đẩy video thương hiệu'},
             {k:'c',t:'Người xem thấy người giống mình dùng thật, không phải người được trả tiền'},{k:'d',t:'Vì video khách quay luôn ngắn hơn video quảng cáo'}],
    answer:'c', why:{a:'Video khách quay thường kém đẹp hơn; sức thuyết phục đến từ sự thật.',
      b:'Thuật toán có thể phân phối cả hai; lý do chính là niềm tin.',
      c:'Đúng. UGC là bằng chứng xã hội từ người không có lợi ích trong việc bán hàng.',
      d:'Độ dài không phải lý do; nhiều video quảng cáo cũng ngắn.'} },
  { type:'mcq', stem:'Thương hiệu muốn đăng lại video của khách lên trang chính thức. Việc cần làm trước là gì?',
    options:[{k:'a',t:'Xin phép khách và ghi rõ nguồn khi đăng lại'},{k:'b',t:'Cắt bỏ phần khách nói chưa hay rồi đăng như video của thương hiệu'},
             {k:'c',t:'Đăng ngay, vì video đã công khai trên mạng xã hội thì dùng tự do'},{k:'d',t:'Trả tiền cho khách rồi yêu cầu quay lại theo kịch bản'}],
    answer:'a', why:{a:'Đúng. Xin phép giữ quan hệ với khách, và ghi nguồn giữ được tính chân thật.',
      b:'Cắt ghép và nhận là của mình làm mất đúng giá trị "khách thật nói".',
      c:'Công khai không có nghĩa là thương hiệu được dùng tự do.',
      d:'Quay theo kịch bản biến UGC thành quảng cáo, mất sức thuyết phục.'} },
  { type:'mcq', stem:'Một shop quần áo hỏi: nên xin đánh giá ngay khi giao hàng thành công, hay sau vài ngày?',
    options:[{k:'a',t:'Ngay lúc giao, vì khách còn nhớ rõ đơn hàng và dễ đánh giá'},{k:'b',t:'Sau vài ngày, khi khách đã mặc thử và có ảnh thật để đăng'},
             {k:'c',t:'Sau một tháng, khi khách đã giặt vài lần và đánh giá độ bền'},{k:'d',t:'Không cần hỏi, khách hài lòng sẽ tự đánh giá mà không cần nhắc'}],
    answer:'b', why:{a:'Lúc giao khách chưa mặc; đánh giá chỉ nói được về đóng gói.',
      b:'Đúng. Sau khi mặc thử là lúc có trải nghiệm và ảnh để chia sẻ.',
      c:'Một tháng là quá lâu; nhiều khách đã quên.',
      d:'Phần lớn khách hài lòng không tự đánh giá nếu không được nhắc.'} } ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tu04-08', skill:'brand', read:'6 phút', t:'Nên thuê KOL hay nuôi cộng đồng đại sứ từ chính khách hàng?',
  situation:'Một thương hiệu đồ chạy bộ ở TP.HCM có 50 triệu đồng mỗi quý. Lựa chọn một: thuê một KOL thể thao đăng 2 bài. Lựa chọn hai: chọn 25 khách đang chạy đều, tặng đồ, mời chạy nhóm hằng tuần và cho mã giới thiệu riêng. Giám đốc thích lựa chọn một vì "có lượt xem ngay".',
  concept:{ name:'Chương trình đại sứ từ khách hàng',
    body:'Đại sứ là những khách <b>đã yêu sản phẩm</b>, được thương hiệu chăm sóc để họ tiếp tục dùng và nói về nó trong vòng tròn của mình. Họ ít người theo dõi hơn KOL, nhưng lời họ nói được tin hơn và lặp lại lâu dài. Chọn đại sứ theo mức dùng thật và độ ảnh hưởng trong nhóm (trưởng nhóm chạy, huấn luyện viên), không theo số người theo dõi. Cho họ thứ mà tiền mua không có: sản phẩm sớm, gặp đội sản phẩm, được góp ý. Đo bằng mã riêng.' },
  example:'Thương hiệu chọn lựa chọn hai. Mỗi đại sứ nhận đồ trị giá 1 triệu, cộng 1 triệu chi phí chạy nhóm mỗi quý: tổng 50 triệu. Sau một quý, 25 đại sứ mang về 400 đơn qua mã riêng, chưa kể bạn chạy nhóm mua không dùng mã. Chi phí mỗi đơn qua đại sứ: 50 triệu ÷ 400 = 125.000đ. Hai bài KOL quý trước mang 150 đơn: khoảng 333.000đ mỗi đơn.',
  takeaway:'Đại sứ từ khách thật nói ít người nghe hơn KOL, nhưng được tin hơn và nói lâu hơn.',
  apply:'Nghĩ về một thương hiệu bạn thích. Nói trong 60 giây: nếu được mời làm đại sứ, bạn muốn nhận gì ngoài tiền.',
  mistakes:['Chọn đại sứ theo số người theo dõi thay vì mức yêu sản phẩm.','Trả tiền cho mỗi bài đăng, biến đại sứ thành người quảng cáo thuê.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: với 50 triệu, 2 bài KOL hay 25 khách đại sứ — bạn đoán bên nào cho đơn rẻ hơn về lâu dài?',
    options:[{k:'a',t:'KOL, vì lượt xem lớn luôn đi kèm nhiều đơn hàng hơn'},{k:'b',t:'Ngang nhau, vì cùng ngân sách 50 triệu thì kết quả phải tương đương'},
             {k:'c',t:'KOL, vì người theo dõi của KOL là người mê thể thao sẵn rồi'},{k:'d',t:'Đại sứ, vì lời khách thật được tin và nói lặp lại lâu dài'}],
    answer:'d', why:{a:'Lượt xem không tự đổi thành đơn; niềm tin mới quyết định.',
      b:'Cùng ngân sách không có nghĩa cùng kết quả.',
      c:'Người theo dõi có thể thích thể thao nhưng biết đây là bài trả tiền.',
      d:'Đúng. Đại sứ nói liên tục trong nhóm chạy, người nghe tin họ.'} },
  { type:'mcq', stem:'Bạn phải chọn 25 đại sứ trong 3.000 khách. Bạn chọn theo tiêu chí nào?',
    options:[{k:'a',t:'Khách có nhiều người theo dõi trên Instagram nhất trong danh sách khách hàng'},{k:'b',t:'Khách mua nhiều tiền nhất trong năm qua'},
             {k:'c',t:'Khách chạy đều, dùng sản phẩm thật và có vai trò trong nhóm chạy'},{k:'d',t:'Khách vừa mua lần đầu, để tạo động lực cho họ mua tiếp'}],
    answer:'c', why:{a:'Nhiều người theo dõi nhưng không dùng thật thì lời nói không đáng tin.',
      b:'Mua nhiều tiền chưa chắc có ảnh hưởng hay chịu nói về sản phẩm.',
      c:'Đúng. Dùng thật và có tiếng nói trong nhóm là hai điều kiện quan trọng nhất.',
      d:'Khách mới chưa đủ trải nghiệm để làm đại sứ.'} },
  { type:'calc', stem:'Chương trình đại sứ tốn 50 triệu đồng, mang về 400 đơn qua mã riêng. Chi phí mỗi đơn là bao nhiêu nghìn đồng?',
    unit:'nghìn đồng', ans:125, tol:0.5, wrong:[[2000,'SAI_MAU_SO'],[8,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Chi phí mỗi đơn = tổng chi phí ÷ số đơn.','50.000.000 ÷ 400 = 125.000đ = <b>125 nghìn đồng</b>.'] },
  { type:'mcq', stem:'Đại sứ đòi được trả 500.000đ cho mỗi bài đăng. Rủi ro của việc đồng ý là gì?',
    options:[{k:'a',t:'Chi phí sẽ tăng vượt ngân sách quý của chương trình'},{k:'b',t:'Đại sứ sẽ đăng quá nhiều bài và làm người theo dõi chán'},
             {k:'c',t:'Người trong nhóm chạy sẽ ghen tị và bỏ tập cùng'},{k:'d',t:'Họ thành người quảng cáo thuê; lời nói mất đi sự chân thật'}],
    answer:'d', why:{a:'Chi phí là một vấn đề, nhưng rủi ro lớn hơn là mất niềm tin.',
      b:'Đăng nhiều có thể xảy ra, nhưng là hệ quả phụ.',
      c:'Không có dữ kiện về chuyện ghen tị.',
      d:'Đúng. Giá trị của đại sứ là nói vì thích; trả theo bài làm hỏng chính điều đó.'} },
  { type:'mcq', stem:'Sau một quý, mã riêng ghi nhận 400 đơn, nhưng doanh số tại các điểm chạy nhóm tăng rõ hơn thế. Đọc điều này thế nào?',
    options:[{k:'a',t:'Mã riêng chỉ đo phần có thể thấy; nhiều người nghe đại sứ nhưng mua không dùng mã'},{k:'b',t:'Doanh số tăng do đang vào mùa giải chạy bộ, hoàn toàn không liên quan gì đến đại sứ'},
             {k:'c',t:'Đại sứ đang dùng mã sai cách, cần hướng dẫn lại'},{k:'d',t:'Cửa hàng đã đếm trùng các đơn có dùng mã riêng của đại sứ nên số bị đội lên'}],
    answer:'a', why:{a:'Đúng. Mã riêng là số tối thiểu; truyền miệng luôn có phần không đo được qua mã.',
      b:'Có thể có yếu tố mùa, nhưng tăng rõ ở chính các điểm chạy nhóm là tín hiệu gắn với đại sứ.',
      c:'Không có dữ kiện cho thấy dùng mã sai.',
      d:'Đếm trùng sẽ làm số mã cao hơn, không làm doanh số điểm bán tăng.'} },
  { type:'mcq', stem:'Thứ gì có giá trị với đại sứ mà tiền khó mua?',
    options:[{k:'a',t:'Phiếu giảm giá 50% cho mọi đơn hàng'},{k:'b',t:'Được thử mẫu mới trước và góp ý trực tiếp với đội sản phẩm'},
             {k:'c',t:'Tiền hoa hồng tăng dần theo số đơn qua mã riêng'},{k:'d',t:'Được thương hiệu đăng ảnh lên trang chính thức một lần'}],
    answer:'b', why:{a:'Giảm giá quy ra tiền được; không tạo cảm giác "người trong nhà".',
      b:'Đúng. Được biết trước và có tiếng nói tạo gắn bó mà tiền không mua được.',
      c:'Hoa hồng là tiền, biến quan hệ thành giao dịch.',
      d:'Một lần đăng ảnh có giá trị nhỏ và ngắn hạn.'} },
  { type:'mcq', stem:'Một thương hiệu mỹ phẩm muốn làm cộng đồng khách. Họ nên bắt đầu ở đâu?',
    options:[{k:'a',t:'Tạo nhóm Facebook, đăng khuyến mãi mỗi ngày để giữ tương tác'},{k:'b',t:'Mua quảng cáo để kéo thật nhiều thành viên vào nhóm trong tuần đầu tiên'},
             {k:'c',t:'Tìm nơi khách đã tự hỏi đáp về da, và tham gia giúp bằng chuyên môn'},{k:'d',t:'Chỉ mời người có trên 10.000 người theo dõi vào nhóm'}],
    answer:'c', why:{a:'Nhóm chỉ có khuyến mãi là kênh bán hàng, không phải cộng đồng.',
      b:'Nhiều thành viên không cùng quan tâm thì nhóm sẽ im lặng.',
      c:'Đúng. Cộng đồng sống quanh một nhu cầu chung; thương hiệu góp giá trị trước.',
      d:'Lọc theo người theo dõi làm mất chính những khách thật.'} } ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tu04-09', skill:'measure', read:'7 phút', t:'Làm sao đo được truyền miệng khi không có mã giới thiệu?',
  situation:'Một tiệm bánh mì ở Cần Thơ không chạy chương trình giới thiệu, nhưng chủ tiệm tin phần lớn khách mới đến vì "người ta kể". Công cụ quảng cáo chỉ báo 120 khách mới đến từ quảng cáo Facebook trong tháng. Chủ tiệm cần biết có nên tăng quảng cáo hay đầu tư thêm cho trải nghiệm tại tiệm.',
  concept:{ name:'Câu hỏi "biết qua đâu"',
    body:'Truyền miệng phần lớn không để lại dấu vết số: người ta nói chuyện ở quán, nhắn riêng, rồi tự tìm đến. Công cụ đo quảng cáo không thấy phần này. Cách đơn giản nhất là <b>hỏi khách mới</b> một câu: "Anh chị biết tiệm qua đâu?", với vài lựa chọn cố định (bạn bè/người thân kể, mạng xã hội, đi ngang qua, khác). Hỏi trên một mẫu đủ lớn, ghi đều đặn, và so theo thời gian. Kết quả không chính xác tuyệt đối vì người ta nhớ không đủ, nhưng cho biết tỉ trọng.' },
  example:'Nhân viên hỏi 300 khách mới trong tháng: 150 nói "bạn kể", 60 nói "thấy trên Facebook", 75 nói "đi ngang qua", 15 khác. Truyền miệng chiếm 50% khách mới. Nếu tiệm có 600 khách mới trong tháng, ước khoảng 300 người đến nhờ truyền miệng, gấp hơn hai lần 120 khách công cụ quảng cáo báo. Chủ tiệm quyết định giữ quảng cáo ở mức hiện tại và dành tiền tăng thêm cho việc làm bánh mới ra lò mỗi giờ — chi tiết khách hay kể.',
  takeaway:'Truyền miệng không để lại dấu vết số; hỏi khách mới "biết qua đâu" là cách đo rẻ và đủ dùng.',
  apply:'Viết câu hỏi "biết qua đâu" cho một doanh nghiệp bạn biết, kèm 4 lựa chọn, và nói ai sẽ hỏi, hỏi lúc nào.',
  mistakes:['Chỉ tin số liệu từ công cụ quảng cáo, bỏ qua kênh không đo được.','Hỏi câu mở không có lựa chọn, kết quả không tổng hợp được.'],
  q:[
  { type:'mcq', stem:'Trước khi đọc: công cụ quảng cáo báo 120 khách mới. Bạn đoán con số này nói gì về truyền miệng?',
    options:[{k:'a',t:'Truyền miệng chỉ chiếm phần nhỏ, vì quảng cáo đã mang về 120 khách'},{k:'b',t:'Truyền miệng bằng 0, vì tiệm không có chương trình giới thiệu'},
             {k:'c',t:'Công cụ quảng cáo đã tính cả khách từ truyền miệng vào con số này rồi'},{k:'d',t:'Không nói gì; công cụ quảng cáo không thấy được truyền miệng'}],
    answer:'d', why:{a:'Không biết tổng số khách mới thì không kết luận được tỉ trọng.',
      b:'Truyền miệng tự nhiên vẫn xảy ra dù không có chương trình.',
      c:'Công cụ quảng cáo chỉ ghi nhận lượt tương tác với quảng cáo.',
      d:'Đúng. Công cụ đo quảng cáo chỉ thấy phần của chính nó.'} },
  { type:'mcq', stem:'Bạn phải thiết kế câu hỏi cho nhân viên hỏi khách mới. Bạn chọn cách nào?',
    options:[{k:'a',t:'"Anh chị thấy quảng cáo của tiệm trên Facebook chưa?"'},{k:'b',t:'"Anh chị biết tiệm qua đâu?" với 4 lựa chọn cố định để đánh dấu'},
             {k:'c',t:'"Anh chị có thích tiệm không?" để đo mức hài lòng'},{k:'d',t:'Để khách tự viết cảm nhận dài vào sổ ở quầy khi thanh toán xong'}],
    answer:'b', why:{a:'Câu hỏi dẫn dắt về Facebook làm lệch kết quả.',
      b:'Đúng. Câu trung lập, lựa chọn cố định, tổng hợp được theo thời gian.',
      c:'Đo hài lòng là chuyện khác; không cho biết kênh.',
      d:'Câu trả lời tự do khó tổng hợp và ít người viết.'} },
  { type:'calc', stem:'Hỏi 300 khách mới: 150 nói "bạn kể". Tiệm có 600 khách mới trong tháng. Ước số khách mới đến nhờ truyền miệng là bao nhiêu?',
    unit:'khách', ans:300, tol:0.5, wrong:[[150,'NHAM_SO_TUYET_DOI'],[450,'SAI_TINH_TOAN']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Tỉ lệ truyền miệng trong mẫu = 150 ÷ 300 = 50%.','Ước tính cho cả tháng = 600 × 50% = <b>300 khách</b>.'] },
  { type:'calc', stem:'Trong mẫu 300 khách mới, 60 người nói "thấy trên Facebook". Tỉ trọng Facebook trong khách mới là bao nhiêu phần trăm?',
    unit:'%', ans:20, tol:0.1, wrong:[[10,'SAI_MAU_SO'],[40,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ trọng = 60 ÷ 300 = 0,2 = <b>20%</b>.','Chia cho 600 khách cả tháng (ra 10%) là sai mẫu số, vì 60 chỉ đến từ mẫu 300 người.'] },
  { type:'mcq', stem:'Ba tháng liên tiếp, tỉ lệ "bạn kể" là 50%, 42%, 35% trong khi quảng cáo không đổi. Bạn đọc tín hiệu này thế nào?',
    options:[{k:'a',t:'Truyền miệng đang yếu đi; kiểm tra trải nghiệm tại tiệm có gì đổi'},{k:'b',t:'Quảng cáo đang tốt lên nên lấn dần phần của truyền miệng'},
             {k:'c',t:'Khách đang trả lời sai, nên bỏ câu hỏi này đi cho đỡ tốn công'},{k:'d',t:'Dao động bình thường, cứ chờ vài tháng nữa là sẽ tự lên lại'}],
    answer:'a', why:{a:'Đúng. Xu hướng giảm đều là tín hiệu có gì đó trong trải nghiệm đã thay đổi.',
      b:'Quảng cáo không đổi, nên khó giải thích bằng việc quảng cáo tốt lên.',
      c:'Sai số nhớ có, nhưng xu hướng đều ba tháng thì không phải ngẫu nhiên do nhớ sai.',
      d:'Giảm từ 50% xuống 35% đều đặn không giống dao động.'} },
  { type:'mcq', stem:'Vì sao câu trả lời "biết qua đâu" không nên được coi là chính xác tuyệt đối?',
    options:[{k:'a',t:'Vì khách luôn cố tình nói dối để được nhân viên tặng thêm quà'},{k:'b',t:'Vì nhân viên đứng quầy lúc đông khách sẽ luôn ghi sai câu trả lời'},
             {k:'c',t:'Khách thường nhớ điểm chạm gần nhất, có thể bỏ qua lần nghe kể trước đó'},{k:'d',t:'Vì câu hỏi này chỉ dùng được cho các doanh nghiệp online'}],
    answer:'c', why:{a:'Không có lý do để khách nói dối khi không được lợi gì.',
      b:'Ghi sai có thể có nhưng không phải lý do chính.',
      c:'Đúng. Trí nhớ không hoàn hảo; câu trả lời là tỉ trọng ước lượng, dùng để so theo thời gian.',
      d:'Câu hỏi này rất hợp với cửa hàng tại chỗ.'} },
  { type:'mcq', stem:'Một shop online muốn đo truyền miệng. Cách nào hợp nhất?',
    options:[{k:'a',t:'Thêm câu hỏi "Bạn biết shop qua đâu?" có lựa chọn ở bước đặt hàng'},{k:'b',t:'Đếm số lượt thích trên trang Facebook của shop mỗi tuần và coi đó là số người nghe kể'},
             {k:'c',t:'Chỉ dựa vào báo cáo nguồn truy cập của website'},{k:'d',t:'Gửi khảo sát 30 câu cho khách sau mỗi đơn'}],
    answer:'a', why:{a:'Đúng. Một câu, có lựa chọn, đúng lúc khách mới vừa đặt.',
      b:'Lượt thích không cho biết khách mới đến từ đâu.',
      c:'Người nghe kể thường gõ tên shop trực tiếp; báo cáo ghi là "truy cập trực tiếp", không phải truyền miệng.',
      d:'Khảo sát dài ít người làm; mục tiêu chỉ cần một câu.'} } ] }

]});
